import { spawn } from 'node:child_process';
import { mkdtemp, mkdir, readFile, writeFile, rm, realpath } from 'node:fs/promises';
import { createServer } from 'node:net';
import { createHash } from 'node:crypto';
import path from 'node:path';
const MODULE = 'file:///Users/zhaoxingbo/Workspace/ai-driven/svton/shipkit/dist/shared/file-lock.js';
const ROOT = await realpath(await mkdtemp('/tmp/ship-tcp-independent-'));
const children = [], listeners = [];
const results = [];
const sleep = (ms) => new Promise(r => setTimeout(r, ms));
function worker(file, temp, createParent = false) {
  const code = `
import { withFileLock, lockPortFor, lockKeyOf } from ${JSON.stringify(MODULE)};
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import path from 'node:path';
const file = ${JSON.stringify(file)};
let release;
process.on('message', async (m) => {
  try {
    if (m === 'claim') process.send({event:'claimed', port:await lockPortFor(file)});
    if (m === 'acquire') {
      const key = lockKeyOf(file);
      await withFileLock(file, async () => {
        const gate = new Promise(r => release = r);
        if (${createParent}) await mkdir(path.dirname(file), {recursive:true});
        const old = Number(await readFile(file, 'utf8').catch(() => '0'));
        process.send({event:'entered', key, currentKey:lockKeyOf(file), old, port:await lockPortFor(key)});
        await gate;
        await writeFile(file, String(old+1));
      }, {timeoutMs:800});
      process.send({event:'finished'});
    }
    if (m === 'release') release?.();
    if (m === 'exit') process.exit(0);
  } catch(e) { process.send({event:'error', message:e.message}); }
});
process.send({event:'ready'});
`;
  const child = spawn(process.execPath, ['--input-type=module', '-e', code], {
    env:{...process.env, TMPDIR:temp, TMP:temp, TEMP:temp}, stdio:['ignore','ignore','pipe','ipc']
  });
  children.push(child);
  const messages=[];
  child.on('message', m => messages.push(m));
  child.stderr.on('data', d => messages.push({event:'stderr', text:String(d)}));
  return { child, messages, async wait(event, ms=2500) {
    const end=Date.now()+ms;
    while(Date.now()<end) {
      const found=messages.find(m=>m.event===event);
      if(found) return found;
      if(messages.some(m=>m.event==='error'||m.event==='stderr')) return null;
      await sleep(5);
    }
    return null;
  }};
}
async function finishPair(a,b,file,name,extra={}) {
  const second=await b.wait('entered',400);
  const first=a.messages.find(m=>m.event==='entered');
  a.child.send('release');
  if(second) b.child.send('release');
  await a.wait('finished');
  if(!second) {
    await b.wait('entered');
    b.child.send('release');
  }
  await b.wait('finished');
  const value=await readFile(file,'utf8').catch(() => 'NaN');
  results.push({name, simultaneousSections:second ? 2:1, first, second,
    finalValue:Number(value), expected:2, ...extra, aMessages:a.messages,bMessages:b.messages});
  a.child.send('exit');b.child.send('exit');
}
try {
  // Same absolute resource, but process-local temp directories differ.
  const c1=path.join(ROOT,'tmpdir');
  await mkdir(c1);await mkdir(path.join(c1,'tmpA'));await mkdir(path.join(c1,'tmpB'));
  const file1=path.join(c1,'state.json');await writeFile(file1,'0');
  const a=worker(file1,path.join(c1,'tmpA'));await a.wait('ready');a.child.send('acquire');await a.wait('entered');
  const b=worker(file1,path.join(c1,'tmpB'));await b.wait('ready');b.child.send('acquire');
  await finishPair(a,b,file1,'isolated-TMPDIR');
  // Force the documented allocation exhaustion using only our own listeners.
  const c2=path.join(ROOT,'fallback');await mkdir(c2);await mkdir(path.join(c2,'tmp'));
  const file2=path.join(c2,'state.json');await writeFile(file2,'0');
  const occupied=[];
  for(let i=0;i<64;i++) {
    const port=49152+createHash('sha256').update([file2,String(i)].join('\u0000')).digest().readUInt32BE(0)%16383;
    if(occupied.includes(port))continue;
    const server=createServer(socket=>socket.destroy());
    const ok=await new Promise(r=>{server.once('error',()=>r(false));server.listen(port,'127.0.0.1',()=>r(true));});
    if(ok){listeners.push(server);occupied.push(port);}
  }
  const f=worker(file2,path.join(c2,'tmp'));await f.wait('ready');f.child.send('claim');
  const fallback=await f.wait('claimed');
  for(const server of listeners.splice(0)) await new Promise(r=>server.close(r));
  f.child.send('acquire');await f.wait('entered');
  const g=worker(file2,path.join(c2,'tmp'));await g.wait('ready');g.child.send('acquire');
  await finishPair(f,g,file2,'fallback-cache-versus-published-claim',{fallback,occupiedCandidates:occupied.length});
  // Parent absent on initial acquisition, then created by the transaction.
  const c3=path.join(ROOT,'missing-parent');await mkdir(c3);await mkdir(path.join(c3,'tmp'));
  const file3=path.join(c3,'new','nested','state.json');
  const m=worker(file3,path.join(c3,'tmp'),true);await m.wait('ready');m.child.send('acquire');await m.wait('entered');
  const n=worker(file3,path.join(c3,'tmp'));await n.wait('ready');n.child.send('acquire');
  await finishPair(m,n,file3,'parent-created-inside-critical-section');
  await writeFile(path.join('/tmp/codex-tool-runs/svton/m2-r2-tcp-rereview-20261001','registry-results.json'),JSON.stringify(results,null,2));
  console.log(JSON.stringify(results.map(({name,simultaneousSections,finalValue,first,second,fallback})=>({name,simultaneousSections,finalValue,first,second,fallback})),null,2));
} finally {
  for(const child of children) if(child.exitCode===null) child.kill('SIGTERM');
  for(const server of listeners) await new Promise(r=>server.close(r));
  await sleep(50);await rm(ROOT,{recursive:true,force:true});
}

import { mkdtemp, mkdir, realpath, writeFile, rm } from 'node:fs/promises';
import path from 'node:path';
import { withFileLock, lockKeyOf, heldToken, releaseLockIfOwner } from '/Users/zhaoxingbo/Workspace/ai-driven/svton/shipkit/dist/shared/file-lock.js';
const dir=await realpath(await mkdtemp('/tmp/ship-identity-independent-'));
const file=path.join(dir,'new','nested','state.json');
const original=lockKeyOf(file);
let token;
try {
  await withFileLock(file,async()=> {
    token=heldToken(original);
    await mkdir(path.dirname(file),{recursive:true});
  });
  const result={originalKey:original,currentKey:lockKeyOf(file),
    leakedHoldingAfterSuccessfulReturn:heldToken(original)===token,
    retainedOriginalToken:!!heldToken(original)};
  // Release our OWN leaked holding through its original identity.
  result.cleanedByOriginalIdentity=await releaseLockIfOwner(original,token);
  await writeFile('/tmp/codex-tool-runs/svton/m2-r2-tcp-rereview-20261001/identity-release-result.json',JSON.stringify(result,null,2));
  console.log(JSON.stringify(result));
} finally {
  if(token) await releaseLockIfOwner(original,token);
  await rm(dir,{recursive:true,force:true});
}

